                customerId,
                items: await Promise.all(lineItems),
                invoiceDate: invoiceDate ? new Date(invoiceDate).toISOString() : end,
                invoicePaymentTerm,
            });
            return invoice;
        } else {
            return { message: `No services found for customer: ${customerId}` };
        }
    }
