            const { startTime, endTime } = Billing.billingCycleToTimeRange(data[0]?.offering.billingCycle);
            const entity = new Billing({
                invoiceId,
                businessID,
                customerId,
                startTime,
                endTime,
                billingId: randomUUID(),
