import { Test, TestingModule } from '@nestjs/testing';
import { forwardRef } from '@nestjs/common';
import { InfluxModule } from '../influx/influx.module';
import { CustomerService } from './customer.service';
import { SchedulerModule } from '../scheduler/scheduler.module';
import { SchedulerService } from '../scheduler/scheduler.service';
import { PublicAPIOfferingModule } from '../offering/offering.module';
import { OfferingService } from '../offering/offering.service';
import { UsageModule } from '../usage/usage.module';
import { UsageService } from '../usage/usage.service';
import { InfluxService } from '../influx/influx.service';
import { CustomerEntity } from './entities/customer.entity';
import { aggregationInterval } from '../dimensions/dto/create-dimension.dto';

const OFFERING_ID = 'f7a2ba05-8ee1-4b71-a3ad-0e1d4b7e51e2';
const CUSTOMER_ID = 'b0e93a63-3a76-4a1e-84a1-f89c9b7e2c11';
const BUSINESS_ID = 'myCoolCorp';

describe('CustomerService', () => {
    let service: CustomerService;

    beforeEach(async () => {
        const module: TestingModule = await Test.createTestingModule({
            providers: [CustomerService],
            imports: [
                InfluxModule,
                forwardRef(() => SchedulerModule),
                forwardRef(() => PublicAPIOfferingModule),
                forwardRef(() => UsageModule),
            ],
        }).compile();

        service = module.get<CustomerService>(CustomerService);
    });

    it('should be defined', () => {
        expect(service).toBeDefined();
    });
});

describe('CustomerService offering ownership', () => {
    const offering = {
        offeringId: OFFERING_ID,
        offeringName: 'myCoolOffering',
        dimensions: [{ dimensionId: '12345', aggregationInterval: aggregationInterval.hour }],
    };
    const customerDbModel = {
        _measurement: CustomerEntity._measurement,
        _value: 'myCoolCustomer',
        customerId: CUSTOMER_ID,
        offeringId: OFFERING_ID,
        businessID: BUSINESS_ID,
    };
    const mockTag = jest.fn();
    const mockLoadPoints = jest.fn();
    const mockFindOfferingOne = jest.fn(async () => ({ data: [offering], message: 'Found Offering' }));
    const mockFindUsageForCustomer = jest.fn(async () => [{ dimensionId: '12345', usage: [] }]);
    let service: CustomerService;

    beforeEach(async () => {
        process.env.STAGE = 'unit-test';
        const module: TestingModule = await Test.createTestingModule({ providers: [CustomerService] })
            .useMocker((token) => {
                if (token === InfluxService) {
                    return {
                        loadPoints: mockLoadPoints,
                        getPoint: () => ({ tag: mockTag, stringField: jest.fn() }),
                        getLatestCustomer: jest.fn(async () => [customerDbModel]),
                        getLatestCustomers: jest.fn(async () => [customerDbModel]),
                        getInvoicesForCustomer: jest.fn(async () => []),
                        getAllCustomersWithOfferingId: jest.fn(async () => [customerDbModel]),
                    };
                }
                if (token === SchedulerService) {
                    return { create: jest.fn(), remove: jest.fn() };
                }
                if (token === OfferingService) {
                    return { findOne: mockFindOfferingOne };
                }
                if (token === UsageService) {
                    return { findUsageForCustomer: mockFindUsageForCustomer };
                }
            })
            .compile();
        service = module.get<CustomerService>(CustomerService);
    });

    afterEach(() => {
        jest.clearAllMocks();
    });

    it('should persist the offeringId of a customer', async () => {
        await service.create(
            { customerName: 'myCoolCustomer', email: 'cool@customer.com', businessID: BUSINESS_ID, offeringId: OFFERING_ID },
            'subject'
        );
        expect(mockTag).toBeCalledWith('offeringId', OFFERING_ID);
        expect(mockLoadPoints).toBeCalledTimes(1);
    });

    it('should return the offeringId and the hydrated offering of a customer', async () => {
        const {
            data: [customer],
        } = await service.findOne({ customerId: CUSTOMER_ID, businessID: BUSINESS_ID });
        expect(customer.offeringId).toEqual(OFFERING_ID);
        expect(customer.offering).toEqual(offering);
        expect(mockFindOfferingOne).toBeCalledWith({ businessID: BUSINESS_ID, offeringId: OFFERING_ID });
    });

    it('should find all customers attached to an offering', async () => {
        const { data } = await service.findAllCustomersWithOfferingId({
            businessID: BUSINESS_ID,
            offeringId: OFFERING_ID,
        });
        expect(data.map(({ customerId }) => customerId)).toEqual([CUSTOMER_ID]);
    });

    it('should delete a customer without checking for legacy services', async () => {
        await expect(service.remove({ customerId: CUSTOMER_ID, businessID: BUSINESS_ID })).resolves.toEqual({
            message: 'Deleted Customer',
            customerId: CUSTOMER_ID,
        });
    });

    it('should read usage for a customer', async () => {
        const { data } = await service.findUsageForCustomer(
            { businessID: BUSINESS_ID, customerId: CUSTOMER_ID },
            { aggregationInterval: aggregationInterval.day }
        );
        expect(mockFindUsageForCustomer).toBeCalledWith(
            { businessID: BUSINESS_ID, customerId: CUSTOMER_ID },
            { aggregationInterval: aggregationInterval.day }
        );
        expect(data).toEqual([{ dimensionId: '12345', usage: [] }]);
    });
});

