const OFFERING_ID = 'f7a2ba05-8ee1-4b71-a3ad-0e1d4b7e51e2';
const CUSTOMER_ID = 'b0e93a63-3a76-4a1e-84a1-f89c9b7e2c11';
const BUSINESS_ID = 'myCoolCorp';

describe('UsageService', () => {
    let service: UsageService;

    beforeEach(async () => {
        const module: TestingModule = await Test.createTestingModule({
            providers: [UsageService],
            imports: [
                InfluxModule,
                MeasurementConfigModule,
                PublicAPIDimensionsModule,
                PublicAPIOfferingModule,
                forwardRef(() => PublicAPICustomerModule),
            ],
        }).compile();

        service = module.get<UsageService>(UsageService);
    });

    it('should be defined', () => {
        expect(service).toBeDefined();
    });
});

describe('UsageService usage reads for a customer', () => {
    const offering = {
        offeringId: OFFERING_ID,
        offeringName: 'myCoolOffering',
        dimensions: [
            {
                dimensionId: '12345',
                aggregationInterval: aggregationInterval.hour,
                aggregationMethod: aggregationMethod.sum,
            },
        ],
    };
    const mockGetAggregateUsageForDimension = jest.fn(async () => [{ dimensionId: '12345', usage: [] }]);
    const buildService = async (customer): Promise<UsageService> => {
        const module: TestingModule = await Test.createTestingModule({ providers: [UsageService] })
            .useMocker((token) => {
                if (token === InfluxService) {
                    return { getAggregateUsageForDimension: mockGetAggregateUsageForDimension };
                }
                if (token === MeasurementConfigService || token === DimensionsService) {
                    return {};
                }
                if (token === OfferingService) {
                    return { findOne: jest.fn(async () => ({ data: [offering], message: 'Found Offering' })) };
                }
                if (token === CustomerService) {
                    return { findOne: jest.fn(async () => ({ data: [customer], message: 'Found Customer' })) };
                }
            })
            .compile();
        return module.get<UsageService>(UsageService);
    };

    afterEach(() => {
        jest.clearAllMocks();
    });

    it('should aggregate the usage of the dimensions of the offering of the customer', async () => {
        const service = await buildService({ customerId: CUSTOMER_ID, offeringId: OFFERING_ID });
        await service.findUsageForCustomer(
            { customerId: CUSTOMER_ID, businessID: BUSINESS_ID },
            { aggregationInterval: aggregationInterval.day }
        );
        expect(mockGetAggregateUsageForDimension).toBeCalledWith(
            expect.objectContaining({
                customerId: CUSTOMER_ID,
                businessID: BUSINESS_ID,
                offeringDocument: expect.objectContaining({
                    dimensions: [expect.objectContaining({ aggregationInterval: aggregationInterval.day })],
                }),
            })
        );
    });

    it('should reject usage reads for customers without an offering', async () => {
        const service = await buildService({ customerId: CUSTOMER_ID });
        await expect(
            service.findUsageForCustomer({ customerId: CUSTOMER_ID, businessID: BUSINESS_ID }, {})
        ).rejects.toThrow(ConflictException);
        expect(mockGetAggregateUsageForDimension).not.toBeCalled();
    });
});

