import { InfluxService } from '../../influx/influx.service';
import { UsageEntity } from '../../usage/entities/usage.entity';
import { MeasurementFormat } from './measurement.interface';
import { StandardMeasurementEntity } from './standardMeasurement.entity';

const CUSTOMER_ID = 'b0e93a63-3a76-4a1e-84a1-f89c9b7e2c11';
const DIMENSION_ID = 'da9611bd-e0f3-4c0d-a754-fda5be730872';

describe('StandardMeasurementEntity', () => {
    const mockTag = jest.fn();
    const mockPoint = { tag: mockTag, timestamp: jest.fn(), floatField: jest.fn() };
    const mockInfluxService = { getPoint: () => mockPoint } as unknown as InfluxService;

    afterEach(() => {
        jest.clearAllMocks();
    });

    it('should keep the customerId of a measurement', () => {
        const entity = new StandardMeasurementEntity({
            businessID: 'myCoolCorp',
            customerId: CUSTOMER_ID,
            dimensionId: DIMENSION_ID,
            recordValue: 0.87,
            metadata: {},
            _measurement: UsageEntity._measurement,
        });
        expect(entity.customerId).toEqual(CUSTOMER_ID);
    });

    it('should persist the customerId as an influx tag', () => {
        const entity = new StandardMeasurementEntity({
            businessID: 'myCoolCorp',
            customerId: CUSTOMER_ID,
            dimensionId: DIMENSION_ID,
            recordValue: 0.87,
            metadata: { environment: 'staging' },
            _measurement: UsageEntity._measurement,
        });
        MeasurementFormat.getPointForm(entity, mockInfluxService);
        expect(mockTag).toBeCalledWith('customerId', CUSTOMER_ID);
        expect(mockTag).toBeCalledWith('dimensionId', DIMENSION_ID);
        expect(mockTag).toBeCalledWith('metadata_environment', 'staging');
    });

    it('should restore the customerId from an influx row', () => {
        const entity = MeasurementFormat.toEntity({
            _time: new Date().toISOString(),
            customerId: CUSTOMER_ID,
            dimensionId: DIMENSION_ID,
            _value: 0.87,
            recordValue: 0.87,
            businessID: 'myCoolCorp',
            _field: 'recordValue',
            _measurement: UsageEntity._measurement,
        });
        expect(entity.customerId).toEqual(CUSTOMER_ID);
        expect(entity.dimensionId).toEqual(DIMENSION_ID);
    });

    it('should only allow the customer and dimension enterprise tags', () => {
        const tags = StandardMeasurementEntity.awsTagKeyReducer([
            { Key: 'enterpriseCustomerId', Value: CUSTOMER_ID },
            { Key: 'enterpriseDimensionId', Value: DIMENSION_ID },
            { Key: 'someOtherTag', Value: 'ignored' },
        ]);
        expect(tags).toEqual({ enterpriseCustomerId: CUSTOMER_ID, enterpriseDimensionId: DIMENSION_ID });
    });
});

