    @Optional() @Inject(forwardRef(() => CustomerService)) readonly customerService?: CustomerService
) {}
findAll() {
    return `This action returns all usage`;
}

async findUsageForCustomer({ customerId, businessID }: ReadUsageForCustomerDto, overrides: QueryParamUsageDto) {
    const { offeringId, offering } = await this.findCustomer({ customerId, businessID });
    if (!offeringId) {
        throw new ConflictException(
            `Customer with ID: ${customerId} is not attached to an offering, attach an offering to the customer before reading usage`
        );
    }
    // Customer reads hydrate the offering already, only look it up again when it is missing
    const { dimensions, ...restOfOfferingDoc } =
        offering ?? (await this.offeringService.findOne({ businessID, offeringId })).data[0];

    let setDimensions = dimensions;
    if (overrides?.aggregationInterval) {
        setDimensions = dimensions.map((dimension) => ({
            ...dimension,
            aggregationInterval: overrides.aggregationInterval,
        }));
    }
    const startDate = new Date(Date.now() - ONE_DAY_IN_MS);
    const endDate = new Date();

    UsageService.logger.debug(`Gathering Usage for businessID: ${businessID} and customerId: ${customerId}`);
    const aggregateData = await this.influxService.getAggregateUsageForDimension({
        customerId,
        businessID,
        startTime: overrides?.startTime ? overrides?.startTime : startDate.toISOString(),
        endTime: overrides?.endTime ? overrides?.endTime : endDate.toISOString(),
        influxService: this.influxService,
        offeringDocument: { dimensions: setDimensions, ...restOfOfferingDoc },
    });
    return aggregateData;
}

/**
 * Customers own usage, however the customer module also reads usage, so the customer service is
 * only optionally available here. Fall back to reading the customer configuration directly.
 */
private async findCustomer({ customerId, businessID }: ReadUsageForCustomerDto): Promise<ReadCustomerResponseData> {
    if (this.customerService) {
        const {
            data: [customer],
        } = await this.customerService.findOne({ customerId, businessID });
        return customer;
    }
    const customerConfig = await this.influxService.getLatestCustomer({ businessID, customerId });
    if (!customerConfig.length) {
        throw new NotFoundException(`Customer with ID: ${customerId} not found`);
    }
    return CustomerEntity.dbModelToEntity(customerConfig[0]);
}

async create(createUsageDto: CreateUsageDto): Promise<BasicResponseDTO> {
    const entity = new StandardMeasurementEntity({
        ...createUsageDto,
        recordValue: parseFloat(createUsageDto?.recordValue),
        _measurement: UsageEntity._measurement,
    });

